use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (res: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        // The output matrices have as many rows as y, and as many columns as x.
        res.0.len() == y.len(),
        res.1.len() == y.len(),
        // For every valid row i and column j,
        // first matrix at (i,j) == x[j], second matrix at (i,j) == y[i].
        forall |i: nat, j: nat| i < y.len() && j < x.len() ==>
            res.0[i][j] == x[j],
        forall |i: nat, j: nat| i < y.len() && j < x.len() ==>
            res.1[i][j] == y[i],
{
    let n = x.len();
    let m = y.len();

    // We'll build the two matrices row by row.
    let mut xmat: Vec<Vec<f32>> = Vec::new();
    let mut ymat: Vec<Vec<f32>> = Vec::new();
    let mut i: usize = 0;
    while i < m
        invariant
            i <= m,
            xmat.len() == i,
            ymat.len() == i,
            // For all fully built rows r < i and columns c < n,
            // xmat[r][c] == x[c] and ymat[r][c] == y[r].
            forall |r: nat, c: nat| r < i && c < n ==>
                xmat[r][c] == x[c],
            forall |r: nat, c: nat| r < i && c < n ==>
                ymat[r][c] == y[r],
        decreases m - i,
    {
        // Build row i for both matrices.
        let mut row_x: Vec<f32> = Vec::new();
        let mut row_y: Vec<f32> = Vec::new();
        let mut j: usize = 0;
        while j < n
            invariant
                j <= n,
                row_x.len() == j,
                row_y.len() == j,
                // For all columns c < j, row_x[c] == x[c], row_y[c] == y[i].
                forall |c: nat| c < j ==> row_x[c] == x[c],
                forall |c: nat| c < j ==> row_y[c] == y[i],
            decreases n - j,
        {
            row_x.push(x[j]);
            row_y.push(y[i]);
            j += 1;
        }
        // Now row_x.len() == n and row_y.len() == n.
        xmat.push(row_x);
        ymat.push(row_y);
        i += 1;
    }
    // At this point i == m, so xmat.len() == m, ymat.len() == m.
    (xmat, ymat)
}

} // verus! 

